def merge(intervals):
    if not intervals: return []
    ivs = sorted(intervals, key=lambda x: x[0])
    out = [{'start': ivs[0][0], 'end': ivs[0][1], 'count': 1}]
    for s, e in ivs[1:]:
        if s <= out[-1]['end']:
            out[-1]['end'] = max(out[-1]['end'], e)
            out[-1]['count'] += 1
        else:
            out.append({'start': s, 'end': e, 'count': 1})
    return out
